{
  "compilerOptions": {
    "lib": [
      "ES2023"
    ],
    "module": "commonjs",
    "target": "ES2022",
    "strict": true,
    "isolatedModules": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "forceConsistentCasingInFileNames": true,
    "jsx": "react-jsx",
    "resolveJsonModule": true,
    "noEmit": true,
    "types": [
      "node"
    ]
  },
  "include": [
    "src"
  ]
}

import { Action, ActionPanel, List } from "@raycast/api";

const ITEMS = [
  { id: "docs", title: "Raycast documentation", url: "https://developers.raycast.com" },
  { id: "store", title: "Raycast Store", url: "https://www.raycast.com/store" },
];

/** The "Search" command: a searchable list (Raycast filters it as you type). */
export default function Command() {
  return (
    <List searchBarPlaceholder="Search…">
      {ITEMS.map((item) => (
        <List.Item
          key={item.id}
          title={item.title}
          actions={
            <ActionPanel>
              <Action.OpenInBrowser url={item.url} />
              <Action.CopyToClipboard content={item.url} />
            </ActionPanel>
          }
        />
      ))}
    </List>
  );
}
